    fees = {}
    for area, km in areas_km.items():
        zone = zone_of(area)
        if zone == "X":
            fees[area] = -1
        else:
            distance_m = int(km * 1000)
            fee = delivery_fee_kes(distance_m)
            fees[area] = fee
    return fees
