def fee_labels(distances_m: list[int]) -> list[str]:
    labels = []
    for distance in distances_m:
        if distance <= 0:
            labels.append("Free")
        elif 0 < distance <= 2000:
            labels.append(f"Ksh 150 for {distance}m")
        else:
            km = distance / 1000
            extra_km = max(0, km - 2)
            fee = 150 + extra_km * 40
            labels.append(f"Ksh {fee} for {distance}m")
    return labels
