def cheapest_dish(codes: list[str]) -> str:
    menu_items = get_menu_items()  # Assume this helper fetches all menu items
    valid_codes = [code for code in codes if code in menu_items]
    if not valid_codes:
        return ""
    # Find the cheapest dish
    min_price = float('inf')
    cheapest_code = ""
    for code in valid_codes:
        price = menu_items[code].price  # Assume price is stored in cents as an integer
        if price < min_price:
            min_price = price
            cheapest_code = code
        elif price == min_price:
            if code < cheapest_code:
                cheapest_code = code
    return cheapest_code
